-- Lightstone sets catalog (Garmoth) + refresh lightstone items.
-- Generated by scripts/gen-lightstone-sets.ts

create table if not exists public.lightstone_sets (
  id text primary key,
  name_ru text not null,
  name_en text,
  category text not null check (category in ('combat', 'lifeskill')),
  bonuses jsonb not null default '[]'::jsonb,
  normal_codex_ids text[] not null,
  enhanced_codex_ids text[] not null,
  updated_at timestamptz not null default now()
);

grant select on public.lightstone_sets to bdokeep_app;

on conflict (id) do update set
  name_ru = excluded.name_ru,
  name_en = excluded.name_en,
  category = excluded.category,
  bonuses = excluded.bonuses,
  normal_codex_ids = excluded.normal_codex_ids,
  enhanced_codex_ids = excluded.enhanced_codex_ids,
  updated_at = now();

on conflict (id) do update set
  name_ru = excluded.name_ru,
  name_en = excluded.name_en,
  category = excluded.category,
  bonuses = excluded.bonuses,
  normal_codex_ids = excluded.normal_codex_ids,
  enhanced_codex_ids = excluded.enhanced_codex_ids,
  updated_at = now();

on conflict (id) do update set
  name_ru = excluded.name_ru,
  name_en = excluded.name_en,
  category = excluded.category,
  bonuses = excluded.bonuses,
  normal_codex_ids = excluded.normal_codex_ids,
  enhanced_codex_ids = excluded.enhanced_codex_ids,
  updated_at = now();

delete from public.lightstone_sets where id not in ('prayer-for-victory', 'well-prepared', 'judging-evil', 'clearing-shadows', 'establishing-order', 'clearing-ranks', 'goddess-song', 'goddess-aide', 'annihilating-shadows', 'hunting-beasts', 'goddess-blessing', 'the-wild', 'the-wild-humans', 'the-wild-demihumans', 'the-wild-kamasylvia', 'the-wild-edania', 'dedication', 'way-of-the-fighter', 'progress', 'building-the-vanguard', 'battle-aid', 'organizing-ranks', 'inner-peace', 'reinforcing-the-vanguard', 'impregnable-fortress', 'crocodiles-tooth', 'vicious-shadows', 'boulder', 'choice-focus', 'golden-hand', 'blacksmiths-blessing', 'deathblow', 'lost-angel-wings', 'know-it-all', 'trained', 'emergency-landing', 'trainee', 'im-mad', 'savage', 'silent-rage', 'focused', 'sprint', 'marathon', 'trained-fists', 'enhanced-focus', 'improved-breathing', 'stomping', 'flying-kick', 'behind-the-shadow', 'target-openings', 'skill-master', 'self-defense', 'shell', 'rigid-shield', 'light-footed', 'centaurus', 'steel-shield', 'water-of-life', 'steel-heart', 'veteran', 'warrior-bloodline', 'last-gatekeeper', 'oluns-descendant', 'fast-ragious', 'mind-focus', 'fasting', 'panting', 'merciless', 'sweep', 'raised-from-the-dead', 'flying-marksmen', 'watch-your-back', 'expose-weakness', 'all-out-attack', 'maiming', 'take-off', 'wondrous-journey', 'training', 'training-humans', 'training-demihumans', 'training-kamasylvia', 'drills-blight-roar', 'drills-blight-fallen', 'drills-fallen-roar');

on conflict (codex_id) do update set
  name_ru = excluded.name_ru,
  icon_url = coalesce(excluded.icon_url, items.icon_url),
  item_type = 'lightstone',
  raw = excluded.raw,
  updated_at = now();

on conflict (codex_id) do update set
  name_ru = excluded.name_ru,
  icon_url = coalesce(excluded.icon_url, items.icon_url),
  item_type = 'lightstone',
  raw = excluded.raw,
  updated_at = now();

delete from public.items where item_type = 'lightstone' and codex_id is not null and codex_id not in ('758001', '758002', '758003', '758004', '758005', '758006', '758007', '758008', '758009', '758010', '758011', '758017', '758018', '758019', '758020', '758021', '758201', '758202', '758203', '758204', '758205', '758206', '758207', '758208', '758209', '758210', '758211', '758217', '758218', '758219', '758220', '758221', '760001', '760002', '760003', '760004', '760005', '760006', '760007', '760009', '760010', '760201', '760202', '760203', '760204', '760206', '760207', '760209', '760210', '762001', '762002', '762003', '762004', '762005', '762006', '762007', '762201', '762202', '762203', '762204', '762205', '762206', '762207', '764001', '764002', '764003', '764004', '764005', '764006', '764007', '764008', '764009', '764010', '764011', '764012', '764013', '764014', '764015', '764016', '764017', '764018', '764019', '764020', '764021', '766101') and id not in (select item_id from public.guide_lightstones);
